import numpy as np, itertools
lines=open('opt1.xyz').read().split('\n'); n=int(lines[0].split()[0])
s=[];x=[]
for l in lines[2:2+n]:
    p=l.split(); s.append(p[0]); x.append([float(v) for v in p[1:4]])
x=np.array(x)
cov={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'F':0.57,'B':0.84,'Br':1.20,'Ag':1.45}
adj={i:set() for i in range(n)}
for i,j in itertools.combinations(range(n),2):
    d=np.linalg.norm(x[i]-x[j])
    if d < cov[s[i]]+cov[s[j]]+0.45:
        adj[i].add(j); adj[j].add(i)
# add dative/coordination bonds
for j in [4,18,32,45]:
    adj[0].add(j); adj[j].add(0)
# BFS
seen={0}; stack=[0]
while stack:
    a=stack.pop()
    for b in adj[a]:
        if b not in seen: seen.add(b); stack.append(b)
print('connected:', len(seen)==n, len(seen), n)
# Ag angles
import numpy as np
vecs=[x[j]-x[0] for j in [4,18,32,45]]
names=['N2a','N2b','N2c','Cc']
for a,b in itertools.combinations(range(4),2):
    v1,v2=vecs[a],vecs[b]
    ang=np.degrees(np.arccos(v1@v2/np.linalg.norm(v1)/np.linalg.norm(v2)))
